/* ===================== BÀI 7 · Segment:offset ===================== */
/* Bài 7 · Segment:offset (AMTS-EMB-002-M02-L03, X86-007) — sinh bởi tools/author/mpu8086/l07.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P7=[{"label": "Ví dụ: tính địa chỉ vật lý của một ô", "code": "; Ví dụ 1: địa chỉ vật lý = đoạn × 16 + độ lệch\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0B800H\n        MOV     ES, AX                  ; ES = B800h: đoạn màn hình\n        MOV     DI, 00A0H               ; 160 = đầu hàng 1 (80 ô × 2 byte)\n        MOV     BYTE PTR ES:[DI], 'S'   ; B8000h + A0h = B80A0h\n        MOV     BYTE PTR ES:[DI+1], 1EH ; thuộc tính ở B80A1h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "ES = B800h, DI = 00A0h: lệnh ghi chữ S vào ES:DI. Phần Thanh ghi vẽ phép tính B800h × 16 + 00A0h = B80A0h; Màn hình DOS hiện chữ S ở đầu hàng thứ hai. Lệnh có tiền tố ES (byte 26h): 10 + EA 5 + 2 = 17 chu kỳ; với [DI+1]: 10 + 9 + 2 = 21. Đoán trước: lệnh ghi thuộc tính ghi vào địa chỉ vật lý nào? Đáp án B80A1h."}, {"label": "Ví dụ: hai cặp đoạn:độ lệch, một ô nhớ", "code": "; Ví dụ 2: hai cặp đoạn:độ lệch, cùng một ô nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndoc     DB      ?                       ; byte đọc lại qua cặp thứ hai\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0B800H\n        MOV     ES, AX\n        MOV     BYTE PTR ES:[0002H], 'H' ; B800:0002 = B8002h\n        MOV     AX, 0B7F0H\n        MOV     ES, AX\n        MOV     AL, ES:[0102H]          ; B7F0:0102 = B7F00h + 102h\n        MOV     doc, AL                 ; = B8002h: đọc lại chữ H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ghi chữ H qua B800:0002 rồi đổi ES = B7F0h và đọc ES:0102. Hai cặp khác nhau nhưng B7F00h + 102h = B8002h = B8000h + 2h: cùng một ô, nên doc = 48h ('H'). Xem hình địa chỉ vật lý của ô nhớ vừa dùng ở hai lệnh. Đoán trước: sau MOV AL, ES:[0102h], AL bằng bao nhiêu? Đáp án 48h."}, {"label": "Lỗi: nạp hằng thẳng vào DS", "code": "; Lỗi: nạp hằng số thẳng vào thanh ghi đoạn\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     DS, 0B800H              ; lỗi: không có lệnh MOV đoạn, hằng\n        MOV     BYTE PTR DS:[0000H], 'A'\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: 8086 không có lệnh nạp hằng số vào thanh ghi đoạn. Trình dịch báo ở dòng 6. Sửa: MOV AX, 0B800h rồi MOV DS, AX."}, {"label": "Bẫy: đổi DS rồi đọc biến", "code": "; Bẫy: đổi DS rồi đọc biến\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkytu    DB      'K'                     ; muốn hiện chữ K lên màn hình\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0B800H\n        MOV     DS, AX                  ; bẫy: lẽ ra phải dùng ES\n        MOV     AL, kytu                ; đọc DS:0000h, giờ là B800:0000h\n        MOV     BX, 0002H\n        MOV     [BX], AL                ; ghi ô hàng 0, cột 1: không phải K\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: sau MOV DS, AX với AX = B800h, biến kytu (độ lệch 0000h) được đọc từ B800:0000 chứ không phải từ đoạn dữ liệu. Trên trình mô phỏng màn hình trống nên AL = 20h (dấu cách) và chữ K không hiện; trên máy thật AL là ký tự đang nằm ở góc trên trái màn hình. Sửa: dùng ES cho màn hình, giữ DS cho biến. Đoán trước: sau MOV AL, kytu, AL có bằng 4Bh ('K') không? Đáp án không (20h)."}, {"label": "Ví dụ: CS cũng là thanh ghi đoạn", "code": "; Ví dụ 5: CS cũng là một thanh ghi đoạn\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nma      DB      2 DUP(?)                ; hai byte đọc từ đoạn mã\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA               ; lệnh đầu: CS:0000h\n        MOV     DS, AX                  ; lệnh thứ hai: CS:0003h\n        MOV     AL, CS:[0000H]          ; byte đầu của đoạn mã\n        MOV     ma, AL\n        MOV     AL, CS:[0003H]          ; byte đầu của lệnh thứ hai\n        MOV     ma+1, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "CS cũng là thanh ghi đoạn: CS:[0000h] là byte đầu của đoạn mã, tức B8h của lệnh MOV AX, @DATA; CS:[0003h] là 8Eh của MOV DS, AX. So với cột byte ở phần Mã máy và chu kỳ. Tiền tố CS là byte 2Eh. Đoán trước: sau MOV AL, CS:[0003h], AL bằng bao nhiêu? Đáp án 8Eh."}, {"label": "Ví dụ: hai đoạn kề nhau chồng lên nhau", "code": "; Ví dụ 6: hai đoạn kề nhau chồng lên nhau\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbang    DB      '0123456789ABCDEF'      ; độ lệch 0…15\n        DB      'GHIJ'                  ; độ lệch 16…19\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        INC     AX                      ; đoạn kế tiếp: bắt đầu sau 16 byte\n        MOV     ES, AX\n        MOV     AL, ES:[0000H]          ; ES:0000h = DS:0010h\n        MOV     kq, AL                  ; 'G'\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "ES = DS + 1 nên ES bắt đầu sau DS đúng 16 byte: ES:0000 là DS:0010, byte thứ 17 của bang, chữ G. Hai đoạn chồng lên nhau gần hết 64 KB. Đoán trước: sau MOV AL, ES:[0000h], AL bằng bao nhiêu? Đáp án 47h ('G')."}, {"label": "Lỗi: chép thẳng giữa hai thanh ghi đoạn", "code": "; Lỗi: chép thẳng giữa hai thanh ghi đoạn\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, DS                  ; lỗi: không có lệnh MOV đoạn, đoạn\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: không có lệnh chép thẳng giữa hai thanh ghi đoạn. Trình dịch báo ở dòng 8 kèm cách sửa. Sửa: MOV AX, DS rồi MOV ES, AX (hoặc PUSH DS / POP ES, chương 6)."}];
const sim7=makeX86Sim(document.getElementById("x86-l7"),{id:"s7",presets:P7,file:"BAI7.ASM"});
makeX86Ex(document.getElementById("ex-l7"),sim7,[{"t": "Đọc qua đoạn kề", "d": "Mảng bang có 26 byte: '0123456789ABCDEF' rồi 'ghijklmnop'. Đọc một chữ số d (0–9) bằng INT 21h hàm 08h rồi in ký tự bang[16 + d] bằng INT 21h hàm 02h. Ràng buộc: đặt ES = DS + 1 (đoạn bắt đầu sau DS đúng 16 byte) và đọc ký tự bằng ES:bang[BX] với BX = d; trang chấm kiểm ES = DS + 1 lúc kết thúc. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: in bang[16 + d] qua đoạn ES = DS + 1\n; Bản này còn đọc bang[d] qua DS. Hãy sửa.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbang    DB      '0123456789ABCDEF'      ; độ lệch 0…15\n        DB      'ghijklmnop'            ; độ lệch 16…25\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; Viết code ở đây: ES = DS + 1\n        MOV     AH, 08H\n        INT     21H                     ; AL = chữ số d\n        SUB     AL, '0'                 ; '7' → 7\n        MOV     BL, AL\n        MOV     BH, 0                   ; BX = d\n        MOV     DL, bang[BX]            ; sửa: đọc qua ES\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "0", "out": "g", "regsRel": {"ES": ["DS", 1]}}, {"in": "9", "out": "p", "regsRel": {"ES": ["DS", 1]}}, {"in": "5", "out": "l", "regsRel": {"ES": ["DS", 1]}}, {"in": "3", "out": "j", "regsRel": {"ES": ["DS", 1]}}, {"in": "7", "out": "n", "regsRel": {"ES": ["DS", 1]}}, {"in": "1", "out": "h", "regsRel": {"ES": ["DS", 1]}}]}, {"t": "Một ô, hai cặp", "d": "Đọc 6 phím: đoạn s1 = k1k2, độ lệch o1 = k3k4, đoạn s2 = k5k6 (mỗi cặp phím là một word, phím đầu là byte cao). Tìm độ lệch o2 sao cho s2:o2 trỏ cùng ô nhớ với s1:o1, ghi vào biến dolech (word). Dữ liệu chấm luôn có s2 ≤ s1 và o2 ≤ FFFFh. Code mẫu đã đọc s1 vào BX, o1 vào CX, s2 vào DX. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: độ lệch mới cho cùng một ô nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndolech  DW      ?                       ; giữ nguyên tên biến\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     BH, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     BL, AL                  ; BX = đoạn 1\n        MOV     AH, 08H\n        INT     21H\n        MOV     CH, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     CL, AL                  ; CX = độ lệch 1\n        MOV     AH, 08H\n        INT     21H\n        MOV     DH, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     DL, AL                  ; DX = đoạn 2\n; Viết code ở đây: dolech = CX + (BX - DX) × 16\n        MOV     dolech, CX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AB  AA", "mem": [{"at": "dolech", "word": 8240}]}, {"in": "AAAAAA", "mem": [{"at": "dolech", "word": 16705}]}, {"in": "B!~~A!", "mem": [{"at": "dolech", "word": 36478}]}, {"in": "zz!!z!", "mem": [{"at": "dolech", "word": 9905}]}, {"in": "A~  4 ", "mem": [{"at": "dolech", "word": 62976}]}, {"in": "M-?/A ", "mem": [{"at": "dolech", "word": 65535}]}]}, {"t": "Bộ tính địa chỉ nhanh", "d": "Đọc 4 phím: đoạn = k1k2, độ lệch = k3k4. Tính địa chỉ vật lý 20 bit = đoạn × 16 + độ lệch; ghi 16 bit thấp vào vl (word) và 4 bit cao (bit 16–19) vào vlc (byte). Code mẫu đã đúng nhưng nhân 16 bằng vòng lặp trên ô nhớ nên chậm. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: địa chỉ vật lý 20 bit của đoạn:độ lệch\n; Bản này đúng nhưng dịch bit trên ô nhớ trong vòng\n; lặp nên chậm. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nvl      DW      ?                       ; 16 bit thấp của địa chỉ\nvlc     DB      ?                       ; 4 bit cao (bit 16–19)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     BH, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     BL, AL                  ; BX = đoạn\n        MOV     AH, 08H\n        INT     21H\n        MOV     CH, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     CL, AL                  ; CX = độ lệch\n        MOV     vl, BX                  ; vl = đoạn\n        MOV     vlc, 0\n        MOV     DI, CX                  ; giữ độ lệch trong DI\n        MOV     CX, 4\ndich:\n        MOV     AX, vl\n        ADD     vl, AX                  ; vl × 2, bit tràn vào CF\n        MOV     AL, vlc\n        ADC     vlc, AL                 ; vlc × 2 + CF\n        LOOP    dich\n        ADD     vl, DI                  ; + độ lệch\n        ADC     vlc, 0\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AB  ", "mem": [{"at": "vl", "word": 13376}, {"at": "vlc", "bytes": [4]}]}, {"in": "~~~~", "mem": [{"at": "vl", "word": 26206}, {"at": "vlc", "bytes": [8]}]}, {"in": "    ", "mem": [{"at": "vl", "word": 8736}, {"at": "vlc", "bytes": [2]}]}, {"in": "~~  ", "mem": [{"at": "vl", "word": 2048}, {"at": "vlc", "bytes": [8]}]}, {"in": "zZ0~", "mem": [{"at": "vl", "word": 54814}, {"at": "vlc", "bytes": [7]}]}, {"in": "0000", "mem": [{"at": "vl", "word": 13104}, {"at": "vlc", "bytes": [3]}]}], "perf": {"cycles": 380, "bytes": 70}}]);

makeQuiz("quiz7","score7",[{"q": "Địa chỉ vật lý của cặp 1234:0005 là bao nhiêu?", "o": ["01239h", "12345h", "12340h", "1234005h"], "a": 1, "e": "1234h × 16 = 12340h, cộng 0005h được 12345h. 01239h là cộng thẳng không nhân 16; 12340h quên cộng độ lệch; 1234005h là ghép hai số thành một số dài."}, {"q": "Sau đoạn sau, chữ Z được ghi vào địa chỉ vật lý nào?<pre class=\"mp-asm\">        MOV     AX, 0B800H\n        MOV     ES, AX\n        MOV     DI, 0004H\n        MOV     BYTE PTR ES:[DI], 'Z'<\/pre>", "o": ["B8004h: hàng 0, cột 2 của màn hình", "0B804h: B800h cộng 0004h", "B8000h: DI không ảnh hưởng tới địa chỉ", "04B80h: độ lệch nhân 16 rồi cộng đoạn"], "a": 0, "e": "ES × 16 + DI = B8000h + 4h = B8004h. Mỗi ô màn hình 2 byte nên độ lệch 4 là cột 2 của hàng 0. Nhân 16 áp cho đoạn, không áp cho độ lệch."}, {"q": "Cặp nào <b>không<\/b> trỏ cùng ô nhớ với B800:0010?", "o": ["B801:0000", "B810:0000", "B7FF:0020", "B000:8010"], "a": 1, "e": "B810:0000 = B8100h. Ba cặp còn lại đều là B8010h: tăng đoạn 1 thì giảm độ lệch 10h (16)."}, {"q": "Lệnh <code>MOV AL, [BP+2]<\/code> (không có tiền tố) đọc ô nhớ trong đoạn nào?", "o": ["DS, vì mọi biến và địa chỉ đều dùng DS", "CS, vì BP trỏ vào khung lệnh đang chạy", "ES, vì BP là thanh ghi đoạn phụ", "SS, vì mọi địa chỉ có BP mặc định thuộc đoạn ngăn xếp"], "a": 3, "e": "Địa chỉ có BP mặc định dùng SS (BP dùng để đọc tham số trên ngăn xếp, chương 6). Muốn dùng DS phải viết DS:[BP+2]."}, {"q": "Dòng nào trong đoạn sau bị trình dịch báo lỗi?<pre class=\"mp-asm\">        MOV     AX, 0B800H              ; dòng 1\n        MOV     ES, AX                  ; dòng 2\n        MOV     DS, ES                  ; dòng 3\n        MOV     AL, ES:[0]              ; dòng 4<\/pre>", "o": ["Dòng 3: không chép thẳng giữa hai thanh ghi đoạn", "Dòng 2: không nạp ES từ AX được", "Dòng 4: tiền tố ES chỉ dùng cho lệnh chuỗi", "Dòng 1: hằng 0B800h quá lớn cho AX"], "a": 0, "e": "8086 không có lệnh MOV thanh_ghi_đoạn, thanh_ghi_đoạn; phải qua AX (MOV AX, ES / MOV DS, AX). MOV ES, AX hợp lệ, và tiền tố ES dùng được cho mọi toán hạng bộ nhớ."}]);

